import django
from django.conf import settings
settings.configure(
    INSTALLED_APPS=['django.contrib.contenttypes', 'django.contrib.auth'],
    DATABASES={'default': {'ENGINE': 'django.db.backends.sqlite3', 'NAME': ':memory:'}},
)
django.setup()
from django.db import models
from django.utils.functional import lazy


class FooBar(models.Model):
    foo_bar = models.CharField(max_length=10, choices=[(1, 'foo'), (2, 'bar')])

    def __str__(self):
        return self.get_foo_bar_display()

    def get_foo_bar_display(self):
        return "something"

    class Meta:
        app_label = 'repro'


class Baz(models.Model):
    baz = models.CharField(max_length=10, choices=[(1, 'foo'), (2, 'bar')])

    class Meta:
        app_label = 'repro'


class PropModel(models.Model):
    choice = models.IntegerField(choices=[(1, 'one')])

    @property
    def get_choice_display(self):
        return "prop"

    class Meta:
        app_label = 'repro'


class AbstractBase(models.Model):
    kind = models.CharField(max_length=10, choices=[(1, 'foo')])

    class Meta:
        abstract = True


class ConcreteChild(AbstractBase):
    class Meta:
        app_label = 'repro'


class OverridingChild(AbstractBase):
    def get_kind_display(self):
        return "child-custom"

    class Meta:
        app_label = 'repro'


class Parent(models.Model):
    kind2 = models.CharField(max_length=10, choices=[(1, 'foo')])

    class Meta:
        app_label = 'repro'


class MTIChild(Parent):
    def get_kind2_display(self):
        return "mti-custom"

    class Meta:
        app_label = 'repro'


# explicit override wins
assert FooBar(foo_bar=1).get_foo_bar_display() == "something", FooBar(foo_bar=1).get_foo_bar_display()
assert str(FooBar(foo_bar=1)) == "something"
# default generated display still works
assert Baz(baz=1).get_baz_display() == 'foo'
assert Baz(baz=2).get_baz_display() == 'bar'
assert Baz().get_baz_display() == ''
# property override respected
assert PropModel(choice=1).get_choice_display == "prop"
# inherited field from abstract base still gets display method
assert ConcreteChild(kind=1).get_kind_display() == 'foo'
assert OverridingChild(kind=1).get_kind_display() == 'child-custom'
# multi-table inheritance override respected
assert MTIChild(kind2=1).get_kind2_display() == 'mti-custom'
print("ALL REPRO ASSERTIONS PASSED")
EOF
